"на посту {0} · защитников {1} из {2}":"nöbette: {0} · savunucu: {1}/{2}",
"устал: уровень −{0}% · домой через {1} ч":"yorgun: seviye −%{0} · eve {1} sa sonra",
"в полной силе ещё {0} ч":"tam güçte, {0} sa daha",
"святилище твоей мифологии · дань {0}":"mitolojinin tapınağı · haraç {0}",
"Святилища рядом (≈5 км)":"Yakındaki Mabetler (≈5 km)",
"Святилища по всему свету":"Dünya genelinde Mabetler",
"Мои защитники":"Savunucularım",
"{0} из {1}":"{0}/{1}",
"Пока нигде. Победи в Святилище и поставь защитника — каждый день будет приходить дань.":"Henüz hiçbir yerde. Bir Mabette kazan ve savunucu koy — her gün haraç gelir.",
"Дань — ✦ {0}, оберег и {1} {2} в день за каждое Святилище, где твой защитник отстоял хотя бы {3} ч. Защитник стоит до {4} суток и понемногу устаёт; если соперники его победят или срок выйдет, он вернётся с искрами за время на посту. Часть Святилищ — вольные: их не держит ни один клан.":"Haraç — savunucunun en az {3} sa durduğu her Mabet için günde ✦ {0}, tılsım ve {1} {2}. Savunucu en çok {4} gün durur ve yavaş yavaş yorulur; rakipler onu yenerse ya da süre dolarsa görev süresine göre kıvılcımla döner. Mabetlerin bir kısmı özgürdür: onları hiçbir klan tutmaz.",
"На святилищах мифологии твоего клана искры и обереги дани — {0}.":"Klanının mitolojisinin tapınaklarında haraçtaki kıvılcım ve tılsımlar {0}.",
