"Быстрота и отвага":"Hız ve cesaret",
"Наследники княжеских дружин под знаком сокола-Рарога. Когда Кощей расколол Алатырь, они первыми встали у Святилищ и держат Навь громом Перуна.":"Rarog şahininin işareti altında prens drujinalarının mirasçıları. Koschei Alatyr'ı kırdığında Mabetlerin başına ilk onlar geçti ve Nav'ı Perun'un gök gürültüsüyle zapt ediyorlar.",
