"Щит к щиту":"Kalkan kalkana",
"Ловчие, что сомкнули щиты под знаком совы Афины. В Перепутицу они стерегут храмы, чтобы тени Аида не вышли к живым.":"Athena'nın baykuşunun işareti altında kalkanlarını birleştiren Avcılar. Büyük Düğüm'de Hades'in gölgeleri yaşayanların arasına çıkmasın diye tapınakları bekliyorlar.",
"Хирд Асгарда":"Asgard Hirdi",
