"Верность и чутьё":"Sadakat ve sezgi",
"Верные, как волки Одина. Хирд стоит у рунных камней, пока не затянутся трещины к Гиннунгагапу.":"Odin'in kurtları kadar sadık. Hird, Ginnungagap'a açılan çatlaklar kapanana dek rün taşlarının başında durur.",
"Братство Дуба":"Meşe Kardeşliği",
"Медведь":"Ayı",
"друид":"druid",
"Сила и стойкость":"Güç ve dayanıklılık",
"Друиды и воины священных рощ под рукой медведицы Артио. Братство держит каменные круги, чтобы холмы сидов не распахнулись навсегда.":"Dişi ayı Artio'nun himayesinde kutsal korulardan druidler ve savaşçılar. Kardeşlik, peri tepeleri sonsuza dek açılmasın diye taş çemberleri tutuyor.",
"Стражи Дуата":"Duat Muhafızları",
