"страж":"muhafız",
"Солнце взойдёт снова":"Güneş yine doğacak",
"Хранители солнечной ладьи Ра. Пока Алатырь расколот, стражи стоят у обелисков, чтобы ночь Дуата не поглотила рассвет.":"Ra'nın güneş kayığının bekçileri. Alatyr kırık kaldıkça muhafızlar, Duat'ın gecesi şafağı yutmasın diye dikilitaşların başında durur.",
"Небесная Гвардия":"Göksel Muhafızlar",
"Дракон":"Ejderha",
"гвардеец":"muhafız askeri",
"Небо и земля в равновесии":"Gök ve yer dengede",
"Воины под знаменем Лазурного дракона. В Перепутицу гвардия держит пагоды, чтобы Небесные врата не остались распахнутыми.":"Gök Mavisi Ejderha'nın sancağı altındaki savaşçılar. Büyük Düğüm'de muhafızlar, Göksel Kapılar ardına kadar açık kalmasın diye pagodaları tutar.",
"Орден Ягуара":"Jaguar Tarikatı",
"Ягуар":"Jaguar",
"воин-ягуар":"jaguar savaşçısı",
"Солнце не должно погаснуть":"Güneş sönmemeli",
"Самые отважные воины древних городов Америки. Орден держит пирамиды, чтобы из Миктлана не пришла вечная ночь.":"Amerika'nın kadim şehirlerinin en yürekli savaşçıları. Tarikat, Mictlan'dan sonsuz gece gelmesin diye piramitleri tutar.",
"Клан «{0}»":"“{0}” Klanı",
