"Вместе — за Алатырь":"Alatyr için birlikte",
"Ловчие мифологии «{0}»: они держат её святилища, пока Алатырь расколот.":"“{0}” mitolojisinin Avcıları: Alatyr kırık kaldıkça onun tapınaklarını tutarlar.",
"Ученик":"Çırak",
"Мастер":"Usta",
"Старейшина":"Ulu",
"Святки":"Svyatki",
"Зимние праздники: Морозко и Снегурка выходят к людям, духи Ветра и Воды встречаются чаще, в источниках — подарки.":"Kış bayramları: Morozko ve Snegurka insanların arasına çıkar, Rüzgâr ve Su ruhları daha sık görülür, kaynaklarda hediyeler var.",
"Масленица":"Maslenitsa",
"Провожаем зиму! Духи Огня встречаются вдвое чаще, в источниках много мёда («блинов»), опыт ×1,5.":"Kışı uğurluyoruz! Ateş ruhları iki kat sık çıkar, kaynaklarda bol bal (“krep”) var, XP ×1,5.",
"Купальская ночь":"Kupala Gecesi",
"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"Eğreltiotu çiçek açtı: Kupalinka her yerde, Ateş, Su ve Orman ruhları daha sık, geceleri parıltılılar iki kat sık.",
"Покров":"Pokrov",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в источниках больше добычи.":"İlk sisler ve kırağı: Rüzgâr ve Su ruhları daha sık çıkar, Listopadnitsa her yerde, kaynaklarda daha çok ganimet var.",
"Велесова ночь":"Veles Gecesi",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"Dünyalar arasındaki sınır en ince hâlinde: Gölge ruhları üç kat sık, büyük yarıklarda Koschei bekliyor, parıltılı Gölgeler iki kat sık.",
"Этот источник теперь принадлежит Нави!":"Bu kaynak artık Nav'ın!",
"Твои духи будут служить Кощею!":"Ruhların Koschei'ye hizmet edecek!",
"Орден Оберега? Никогда о таком не слышал.":"Tılsım Tarikatı mı? Hiç duymadım.",
"Граница рухнет, и мы заберём весь город!":"Sınır çökecek ve bütün şehri alacağız!",
"Думаешь, оберегом меня остановишь?":"Beni bir tılsımla durdurabileceğini mi sanıyorsun?",
"Тьма уже здесь, Ловчий. Смирись.":"Karanlık çoktan burada, Avcı. Kabullen.",
