"Плащ Ордена Оберега — с него начинает каждый Ловчий.":"Tılsım Tarikatı'nın pelerini — her Avcı onunla başlar.",
"Купальский":"Kupala",
"Венок с цветком папоротника, что расцветает лишь в Купальскую ночь.":"Yalnızca Kupala gecesi açan eğreltiotu çiçeğinden bir çelenk.",
"Капюшон из мха и оленьи рога — леса признают тебя своим.":"Yosundan kapüşon ve geyik boynuzları — ormanlar seni kendilerinden sayar.",
"Морозный":"Ayazlı",
"Ледяной венец и иней на плаще. Подарок самого Морозко.":"Buzdan taç ve pelerinde kırağı. Bizzat Morozko'nun hediyesi.",
"Волхв":"Volkhv",
"Шапка с рунами и посох с огоньком: мудрость старых волхвов.":"Runlu şapka ve ucu ışıklı asa: eski volkhvların bilgeliği.",
"Богатырь":"Bogatyr",
"Шелом, кольчуга и алое корзно — хоть сейчас на заставу.":"Miğfer, zincir zırh ve al pelerin — hemen sınır karakoluna gitmeye hazır.",
"Вороний":"Kuzgun",
"Маска-клюв и плащ из чёрных перьев. Вороны Нави шепчут тебе вести.":"Gagalı maske ve kara tüylerden pelerin. Nav'ın kuzgunları sana haber fısıldar.",
"Навий страж":"Nav muhafızı",
"Рогатая личина и пламя Нави. Духи расступаются перед тобой.":"Boynuzlu maske ve Nav alevi. Ruhlar önünde yol açar.",
"Жар-перо":"Kor tüy",
"Убор из огненных перьев Жар-птицы. Светится даже в самую тёмную ночь.":"Zhar-Ptitsa'nın alevli tüylerinden bir başlık. En karanlık gecede bile parlar.",
"Княжий":"Prens",
"Княжья шапка с соболем и самоцветами — наряд первых Ловчих Ордена.":"Samurlu ve değerli taşlı prens külahı — Tarikat'ın ilk Avcılarının kıyafeti.",
