"Северное сияние":"Kutup ışıkları",
"Иней":"Kırağı",
"Навья луна":"Nav ayı",
"Золотая роспись":"Altın nakış",
"Врата Нави":"Nav Kapısı",
"Без рамки":"Çerçevesiz",
"Золотая кайма":"Altın kenar",
"Рунная кайма":"Runik kenar",
"Ледяной узор":"Buz deseni",
"Огненная кайма":"Alev kenarı",
"Жемчужная":"İnci",
"Змей-уроборос":"Ouroboros yılanı",
"Навий шип":"Nav dikeni",
"Княжий оклад":"Prens çerçevesi",
"Поединщик":"Düellocu",
"Победи хранителей святилищ":"Mabet bekçilerini yen",
"Победи хранителей святилищ: {0}":"Mabet bekçisi yen: {0}",
"Первый дух":"İlk ruh",
"Твои духи":"Ruhların",
"Рядом появился дух — видишь светящийся круг на карте? <b>Коснись духа</b>, а потом <b>смахни оберег вверх</b>, прямо в него.":"Yakında bir ruh belirdi — haritadaki parlayan halkayı görüyor musun? <b>Ruha dokun</b>, sonra <b>tılsımı yukarı kaydır</b>, tam ona.",
"Второй учебный дух рядом. Кольцо вокруг духа сжимается: бросай, когда оно <b>маленькое</b>, — выйдет «Отлично!». Зелёное кольцо — дух покладистый, красное — упрямый.":"İkinci eğitim ruhu yakında. Ruhun etrafındaki halka küçülür: <b>küçükken</b> at — “Harika!” çıkar. Yeşil halka uysal ruh, kırmızı halka inatçı ruh demek.",
"Это меню — здесь все разделы. Пока открыто не всё: разделы откроются по ходу обучения, подсвеченный — следующий.":"Burası menü — tüm bölümler burada. Henüz hepsi açık değil: bölümler eğitim ilerledikçe açılır, vurgulanan sıradaki.",
"Каждый пойманный дух — твой. Открой <b>меню</b> — золотой оберег внизу экрана.":"Yakaladığın her ruh senindir. <b>Menüyü</b> aç — ekranın altındaki altın tılsım.",
"Это твоя коллекция — все пойманные духи. Сверху — сортировка по силе, новизне и имени и фильтр по стихиям.":"Bu senin koleksiyonun — yakaladığın bütün ruhlar. Üstte güce, yeniliğe ve ada göre sıralama ile element filtresi var.",
"Это разделы Ордена. Открой <b>«Духи»</b> — там твоя коллекция.":"Bunlar Tarikat'ın bölümleri. <b>“Ruhlar”</b> bölümünü aç — koleksiyonun orada.",
"Это карточка духа: сила, стихия, приёмы и семейство. Ниже — кнопки «Усилить» и «Превратить», а ещё можно сделать духа спутником.":"Bu ruhun kartı: güç, element, hamleler ve aile. Altta “Güçlendir” ve “Dönüştür” düğmeleri var, ruhu yoldaşın da yapabilirsin.",
"Коснись любого духа, чтобы открыть его <b>карточку</b>.":"Herhangi bir ruhun <b>kartını</b> açmak için ona dokun.",
"На карточке — сила духа. Нажми <b>«Усилить»</b>: за искры и эссенцию дух станет сильнее. Эссенцию приносят поимки духов того же семейства.":"Kartta ruhun gücü yazar. <b>“Güçlendir”</b>'e bas: kıvılcım ve öz karşılığında ruh güçlenir. Özü aynı aileden ruh yakalamak getirir.",
"Бестиарий — все виды духов. Пойманные видны целиком, встреченные — тенью. Коснись вида, чтобы прочитать о нём.":"Bestiyer — bütün ruh türleri. Yakalananlar tam görünür, karşılaşılanlar gölge olarak. Hakkında okumak için bir türe dokun.",
"Теперь загляни в <b>«Бестиарий»</b> (меню) — там все виды духов. Сколько найдёшь ты?":"Şimdi <b>“Bestiyer”</b>'e (menü) bir göz at — bütün ruh türleri orada. Sen kaç tanesini bulacaksın?",
"Обереги пополняют <b>источники</b> — светящиеся чаши у памятников, фонтанов и храмов. Дойди до ближайшего джойстиком по <b>стрелке вверху</b> и коснись его. Если рядом нет — прогуляйся по карте.":"Tılsımlar <b>kaynaklarda</b> yenilenir — anıtların, çeşmelerin ve tapınakların yanındaki parlayan çanaklar. <b>Üstteki oku</b> izleyerek joystick ile en yakınına git ve ona dokun. Yakında yoksa haritada biraz yürü.",
"Сумка: обереги, мёд, живая вода и ладан. Сверху видно, сколько ещё поместится; лишнее можно выбросить.":"Çanta: tılsımlar, bal, Zhivaya Voda ve tütsü. Üstte daha ne kadar sığacağı görünür; fazlasını atabilirsin.",
"Добыча уже в <b>Сумке</b>. Открой меню → «Сумка» и посмотри, что у тебя есть.":"Ganimet zaten <b>Çanta</b>'da. Menü → “Çanta”yı aç ve neyin olduğuna bak.",
"Коконы греются шагами — одновременно можно греть три. Готовый кокон вылупится одним касанием. А твой первый дух идёт рядом — это спутник: в пути он находит эссенцию.":"Kozalar adımlarla ısınır — aynı anda üç koza ısıtabilirsin. Hazır koza tek dokunuşla açılır. İlk ruhun da yanında yürüyor — o senin yoldaşın: yolda öz bulur.",
"Открой меню → <b>«Коконы»</b>. Первый кокон уже греется — пройди 2 км, и он вылупится.":"Menü → <b>“Kozalar”</b>ı aç. İlk koza ısınıyor bile — 2 km yürü, açılsın.",
"Здесь задания дня — они обновляются в полночь. А источники иногда дают поручения: выполнишь — встретишь особого духа.":"Günün görevleri burada — gece yarısı yenilenir. Kaynaklar da bazen vazife verir: tamamlarsan özel bir ruhla karşılaşırsın.",
"Открой <b>«Задания»</b> — там задания дня.":"<b>“Görevler”</b>i aç — günün görevleri orada.",
"Путь Ловчего: что откроется на каждом уровне и какие награды ждут. Звания растут: Послушник, Ловчий, Следопыт, Ведун, Хранитель.":"Avcının Yolu: her seviyede neler açılır ve hangi ödüller bekliyor. Unvanlar yükselir: Acemi, Avcı, İzci, Bilici, Koruyucu.",
"И последнее: открой <b>«Путь»</b> в меню — там видно, что откроется на каждом уровне Ловчего.":"Son olarak: menüden <b>“Yol”</b>u aç — her Avcı seviyesinde neyin açılacağı orada görünür.",
"держит Святилище с {0} · защитников: {1} из {2}":"{0} tarihinden beri Mabedi tutuyor · savunucu: {1}/{2}",
"держит Святилище · защитников: {0} из {1}":"Mabedi tutuyor · savunucu: {0}/{1}",
"Святилище мифологии твоего клана: защитник здесь приносит дань {0}.":"Klanının mitolojisinin tapınağı: buradaki savunucu {0} haraç getirir.",
"Святилище держит твой клан. Поставь сюда своего защитника — и получай дань каждый день.":"Bu Mabet senin klanının elinde. Buraya savunucunu koy — her gün haraç al.",
