"В Telegram откроется бот @{0}. Нажми «Запустить» — и возвращайся сюда: вход завершится сам.":"Telegram’da @{0} botu açılacak. “Başlat”a dokun ve buraya dön — giriş kendiliğinden tamamlanır.",
