"Вход через {0} перейдёт к твоему текущему Ловчему, а у {1} его больше не будет.":"{0} ile giriş mevcut Avcına geçecek, {1} artık bu girişe sahip olmayacak.",
"У того Ловчего есть и другие способы входа — его прогресс останется доступен через них.":"O Avcının başka giriş yolları var — ilerlemesine onlarla ulaşılabilir.",
"<b>У того Ловчего не останется других способов входа — его прогресс станет недоступен навсегда.</b>":"<b>O Avcının başka giriş yolu kalmayacak — ilerlemesi sonsuza dek kaybolacak.</b>",
"Привязать сюда":"Buraya bağla",
"Готово: вход через {0} теперь у этого Ловчего":"Tamam: {0} ile giriş artık bu Avcıya ait",
"Не удалось привязать — попробуй ещё раз":"Bağlanamadı — tekrar dene",
"Вход уже привязан":"Giriş zaten bağlı",
"Вход через {0} привязан к Ловчему {1}.":"{0} ile giriş şu Avcıya bağlı: {1}.",
"Можно перейти в ту учётную запись — тогда текущий гостевой прогресс на этом устройстве останется в прежней учётной записи, вернуться в неё будет нельзя. Или привязать этот вход к текущему Ловчему.":"O hesaba geçebilirsin — bu cihazdaki misafir ilerlemen eski hesapta kalır ve geri dönemezsin. Ya da bu girişi mevcut Avcına bağla.",
"Можно перейти в ту учётную запись — текущий прогресс останется в своей. Или привязать этот вход к текущему Ловчему.":"O hesaba geçebilirsin — mevcut ilerlemen kendi hesabında kalır. Ya da bu girişi mevcut Avcına bağla.",
