"поймано":"yakalandı",
"Гость играет только на этом устройстве — привяжи вход, чтобы не потерять прогресс":"Misafir yalnızca bu cihazda oynar — ilerlemeni kaybetmemek için giriş bağla",
"вход":"giriş",
"Открываю {0}…":"Açılıyor: {0}…",
"Выйти?":"Çıkılsın mı?",
"Прогресс останется в учётной записи — вернуться в неё можно тем же входом. На этом устройстве начнётся новая гостевая игра.":"İlerleme hesapta kalır — aynı girişle ona geri dönebilirsin. Bu cihazda yeni bir misafir oyunu başlar.",
"Выйти из гостевой игры?":"Misafir oyunundan çıkılsın mı?",
"<b>Прогресс гостя пропадёт навсегда</b> — у гостя нет входа, чтобы вернуться.":"<b>Misafir ilerlemesi sonsuza dek kaybolur</b> — misafirin geri dönmek için bir girişi yok.",
"Чтобы сохранить его, сначала привяжи вход через {0}.":"Onu korumak için önce {0} ile giriş bağla.",
