"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Günlük XP {0} değerine kadar tam, {1} değerine kadar yarım, üstü dörtte bir gelir. Eğitim ve Tarikat rozetleri XP'yi her zaman tam verir. Oynamadığın her gün dinlenme XP'si birikir ({2}, en çok {3} {4} için): o varken XP iki kat.",
