"Опыт дают поимки, источники, разломы, святилища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"XP; yakalamalardan, kaynaklardan, yarıklardan, Mabetlerden ve görevlerden gelir. Seviyenle birlikte ruhların da büyür: onları Avcı seviyesi +5'e kadar güçlendirebilirsin.",
