"Источники и Святилища стоят у настоящих мест. Знаешь интересный объект рядом? Предложи его!":"Kaynaklar ve Mabetler gerçek yerlerin yanında durur. Yakında ilginç bir yer mi biliyorsun? Öner!",
"<b>Подходят:</b> памятники, скульптуры, фонтаны, мозаики, необычные здания, храмы, парки, источники, смотровые площадки.":"<b>Uygun olanlar:</b> anıtlar, heykeller, çeşmeler, mozaikler, sıra dışı binalar, tapınaklar, parklar, pınarlar, seyir terasları.",
"<b>Не подходят:</b> частные дома и дворы, школы и детские сады, опасные места (проезжая часть, стройки), обычные магазины.":"<b>Uygun olmayanlar:</b> özel evler ve avlular, okullar ve anaokulları, tehlikeli yerler (araç yolu, inşaatlar), sıradan dükkânlar.",
"Стой рядом с объектом: снимок получает геометку, модератор сверяет её с точкой на карте.":"Nesnenin yanında dur: fotoğraf konum etiketi alır, moderatör onu haritadaki noktayla karşılaştırır.",
