"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"Büyük Düğüm dünyanın yollarını birbirine kattı, Tılsım Tarikatı da Avcılara Kapıları açtı: Dünya Atlası’nda Dünya’nın herhangi bir köşesini seç — avın orada başlayacak. Haritada joystick ile yürü, yeni diyarlara Atlas’tan geç. Oyunun telefonunun gerçek konumuna ihtiyacı yok. İlerlemen oyun sunucusunda saklanır ve yalnızca sana açıktır; sunucu her hamleyi kontrol eder, bu yüzden internet gerekir. Seçtiğin bölgenin harita yerleri ve havası OpenStreetMap ve Open-Meteo’dan yüklenir (hava durumu ayarlardan kapatılabilir).",
"Уже играешь?":"Zaten oynuyor musun?",
"Войди — и твой прогресс откроется на этом устройстве":"Giriş yap — ilerlemen bu cihazda açılsın",
