"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"Giriş bağla: Menü → Ayarlar → Hesap (Google, Yandex, VK, Telegram ya da e-posta). Bunu yapmazsan misafir ilerlemesi aktarılmaz.",
